import logging
import re
from functools import lru_cache
from urllib.parse import parse_qs, urljoin, urlsplit, urlunsplit

import requests
from tenacity import retry, retry_if_exception, stop_after_attempt, wait_exponential
from utils.extract_text import extract_text

logger = logging.getLogger(__name__)

PLATFORM = "eightfoldai"

SEARCH_PATH = "/api/pcsx/search"
DETAIL_PATH = "/api/pcsx/position_details"

JOB_ID_RE = re.compile(r"/careers/job/(\d+)")
DOMAIN_IN_HTML_RE = re.compile(r"""["']?domain["']?\s*[:=]\s*["']([a-z0-9][a-z0-9.\-]+\.[a-z]{2,})["']""", re.I)

EIGHTFOLD_JOB_TYPE_MAP = {
    "full time": "Fulltime",
    "part time": "Intern",
    "contract": "Contract",
    "contractor": "Contract",
    "temporary": "Contract",
    "intern": "Intern",
    "internship": "Intern",
    "seasonal": "Contract",
}

session = requests.Session()
session.headers.update({
    "User-Agent": (
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
        "AppleWebKit/537.36 (KHTML, like Gecko) "
        "Chrome/120.0.0.0 Safari/537.36"
    ),
    "Accept": "application/json, text/plain, */*",
})


class ParseError(Exception):
    """Page or API response loaded but did not look like what we expect."""


def _is_transient(exc: BaseException) -> bool:
    if isinstance(exc, (requests.ConnectionError, requests.Timeout)):
        return True
    if isinstance(exc, requests.HTTPError) and exc.response is not None:
        return exc.response.status_code == 429 or exc.response.status_code >= 500
    return False


@retry(
    retry=retry_if_exception(_is_transient),
    stop=stop_after_attempt(3),
    wait=wait_exponential(multiplier=1, min=2, max=10),
    reraise=True,
)
def _get(url: str, params: dict | None = None) -> requests.Response | None:
    """None on 404. Raises on any other failure."""
    resp = session.get(url, params=params, timeout=20)
    if resp.status_code == 404:
        return None
    resp.raise_for_status()
    return resp


def _normalize_url(url: str) -> str:
    parts = urlsplit(url)
    return urlunsplit((parts.scheme, parts.netloc, parts.path.rstrip("/"), "", ""))


def _origin(url: str) -> str:
    parts = urlsplit(url)
    return f"{parts.scheme}://{parts.netloc}"


@lru_cache(maxsize=256)
def _resolve_domain_for_origin(origin: str, company_url: str) -> str:
    """The pcsx API needs the customer's own domain (e.g. morganstanley.com), which is not
    the Eightfold subdomain. Resolution order:
      1. an explicit ?domain=... on company_url
      2. a domain literal found in the careers page HTML
      3. guess: <subdomain>.com
    If (3) is wrong for some company, pass the right value via ?domain= in company_url.
    """
    qs = parse_qs(urlsplit(company_url).query)
    if qs.get("domain"):
        return qs["domain"][0]

    try:
        resp = _get(company_url)
        if resp is not None:
            for match in DOMAIN_IN_HTML_RE.finditer(resp.text):
                candidate = match.group(1).lower()
                if "eightfold.ai" not in candidate:
                    return candidate
    except requests.RequestException:
        logger.debug("eightfold domain lookup failed for %s", company_url)

    subdomain = urlsplit(origin).netloc.split(".")[0]
    return f"{subdomain}.com"


def _resolve_domain(company_url: str) -> str:
    return _resolve_domain_for_origin(_origin(company_url), company_url)


def list_jobs(company_url: str) -> list[str] | None:
    """Phase 1. Harvest job URLs by paging through /api/pcsx/search."""
    origin = _origin(company_url)
    domain = _resolve_domain(company_url)
    api_url = origin + SEARCH_PATH

    start = 0
    total = None
    job_urls = set()

    while True:
        params = {
            "domain": domain,
            "query": "",
            "location": "",
            "start": start,
            "sort_by": "timestamp",
        }
        resp = _get(api_url, params=params)
        if resp is None:
            return None

        try:
            body = resp.json()
        except ValueError:
            raise ParseError(f"Invalid JSON response from Eightfold API at {api_url}")

        # Some deployments wrap the payload in a "data" key.
        data = body.get("data", body) if isinstance(body, dict) else {}
        positions = data.get("positions") or []
        if not positions:
            break

        if total is None:
            total = data.get("count", 0)

        for pos in positions:
            path = pos.get("positionUrl")
            if not path and pos.get("id"):
                path = f"/careers/job/{pos['id']}"
            if path:
                job_urls.add(_normalize_url(urljoin(origin, path)))

        start += len(positions)
        if start >= total:
            break

    return sorted(job_urls)


def fetch_detail(job_url: str) -> dict | None:
    """Phase 2. Fetch one job via /api/pcsx/position_details."""
    match = JOB_ID_RE.search(urlsplit(job_url).path)
    if not match:
        return None
    position_id = match.group(1)

    origin = _origin(job_url)
    # Detail calls only know the job URL, so derive the domain from the careers root.
    domain = _resolve_domain_for_origin(origin, origin + "/careers")

    resp = _get(
        origin + DETAIL_PATH,
        params={"position_id": position_id, "domain": domain, "hl": "en"},
    )
    if resp is None:
        return None

    try:
        body = resp.json()
    except ValueError:
        raise ParseError(f"Invalid JSON response from Eightfold API for {job_url}")

    data = body.get("data", body) if isinstance(body, dict) else {}
    title = data.get("name")
    if not title:
        raise ParseError(f"No title found in Eightfold API response for {job_url}")

    locations = [loc for loc in (data.get("locations") or []) if loc]
    if not locations and data.get("location"):
        locations = [data["location"]]

    time_types = data.get("efcustomTextTextTimeType") or []
    raw_type = (time_types[0] if time_types else "").lower().replace("-", " ").strip()
    job_type = EIGHTFOLD_JOB_TYPE_MAP.get(raw_type)

    description_html = data.get("jobDescription") or ""
    description_text = extract_text(description_html) if description_html else ""

    canonical_url = data.get("publicUrl") or job_url
    logger.debug("eightfold api job_url=%s title=%r locations=%s", job_url, title, locations)

    return {
        "job_url": _normalize_url(canonical_url),
        "locations": locations,
        "job_type": job_type,
        "salary_range": None,
        "salary_min": None,
        "salary_max": None,
        "job_name": title,
        "description": description_text,
        "platform": PLATFORM,
    }